import socket
import threading
import os
import sys

def validate_ip(ip_str):
    try:
        socket.inet_aton(ip_str)
        return True
    except socket.error:
        return False

def handle_client(client_socket, addr):
    try:
        data = client_socket.recv(1024)
        if data:
            print(f"[{addr[0]}:{addr[1]}] Received: {data.decode('utf-8', errors='ignore')}")
            response = f"Echo: {data.decode('utf-8', errors='ignore')}"
            client_socket.sendall(response.encode('utf-8'))
    except Exception as e:
        print(f"Error handling client {addr}: {e}")
    finally:
        client_socket.close()

def start_server(host, port):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind((host, port))
        server_socket.listen(5)
        print(f"Server listening on {host}:{port}")
        while True:
            client_socket, addr = server_socket.accept()
            client_thread = threading.Thread(target=handle_client, args=(client_socket, addr))
            client_thread.daemon = True
            client_thread.start()
    except KeyboardInterrupt:
        print("\nServer shutting down.")
    finally:
        server_socket.close()

def start_client(host, port):
    try:
        client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        client_socket.connect((host, port))
        print(f"Connected to {host}:{port}")
        while True:
            message = input("Enter message (or 'quit' to exit): ")
            if message.lower() == 'quit':
                break
            client_socket.sendall(message.encode('utf-8'))
            response = client_socket.recv(1024)
            if response:
                print(f"Server response: {response.decode('utf-8', errors='ignore')}")
        client_socket.close()
    except Exception as e:
        print(f"Client error: {e}")

def main():
    host = os.getenv("SERVER_HOST", "127.0.0.1")
    port_str = os.getenv("SERVER_PORT", "8080")

    try:
        port = int(port_str)
        if not (1 <= port <= 65535):
            raise ValueError("Port out of range")
    except ValueError as e:
        print(f"Invalid port configuration: {e}")
        sys.exit(1)

    if not validate_ip(host):
        print("Invalid host IP address")
        sys.exit(1)

    mode = os.getenv("MODE", "server")

    if mode == "server":
        start_server(host, port)
    elif mode == "client":
        start_client(host, port)
    else:
        print("Invalid mode. Set MODE=server or MODE=client in environment variables.")
        sys.exit(1)

if __name__ == "__main__":
    main()
